// Get data from all parallel fetches
const tradeIssues = $('Fetch TRADE Project').all().map(i => i.json);
const infraIssues = $('Fetch INFRA Project').all().map(i => i.json);
const learnIssues = $('Fetch LEARN Project').all().map(i => i.json);
const mgmtIssues = $('Fetch MGMT Project').all().map(i => i.json);
const agents = $('Fetch Agent Heartbeats').first()?.json?.agents || [];
const yesterdayCompleted = $('Fetch Yesterday Completed').all().map(i => i.json);

// Helper to categorize issues
const categorizeIssues = (issues, projectKey) => {
  const inProgress = issues.filter(i => i.fields?.status?.name === 'In Progress');
  const todo = issues.filter(i => i.fields?.status?.name === 'To Do' || i.fields?.status?.name === 'Open');
  const blocked = issues.filter(i => i.fields?.labels?.includes('blocked') || i.fields?.status?.name === 'Blocked');
  const highPriority = issues.filter(i => ['Highest', 'High'].includes(i.fields?.priority?.name));

  return {
    projectKey,
    total: issues.length,
    inProgress: inProgress.length,
    todo: todo.length,
    blocked: blocked.map(i => ({
      key: i.key,
      summary: i.fields?.summary?.substring(0, 80),
      reason: i.fields?.customfield_blockedReason || 'Unknown'
    })),
    highPriorityItems: highPriority.slice(0, 3).map(i => ({
      key: i.key,
      summary: i.fields?.summary?.substring(0, 60),
      status: i.fields?.status?.name,
      assignee: i.fields?.assignee?.displayName || 'Unassigned'
    }))
  };
};

// Process each project
const projects = {
  TRADE: categorizeIssues(tradeIssues, 'TRADE'),
  INFRA: categorizeIssues(infraIssues, 'INFRA'),
  LEARN: categorizeIssues(learnIssues, 'LEARN'),
  MGMT: categorizeIssues(mgmtIssues, 'MGMT')
};

// Aggregate blockers across all projects
const allBlockers = [
  ...projects.TRADE.blocked,
  ...projects.INFRA.blocked,
  ...projects.LEARN.blocked,
  ...projects.MGMT.blocked
];

// Process agent status
const agentStatus = {
  total: agents.length,
  running: agents.filter(a => a.status === 'running' || a.status === 'active').length,
  stopped: agents.filter(a => a.status === 'stopped' || a.status === 'paused').length,
  error: agents.filter(a => a.status === 'error').length,
  agentList: agents.map(a => ({
    name: a.name,
    status: a.status,
    lastHeartbeat: a.lastHeartbeat,
    minutesSinceHeartbeat: a.lastHeartbeat ? 
      Math.round((Date.now() - new Date(a.lastHeartbeat).getTime()) / 60000) : 999
  }))
};

// Stale agents (no heartbeat in 10+ minutes)
const staleAgents = agentStatus.agentList.filter(a => a.minutesSinceHeartbeat > 10);

// Format yesterday's completions
const completedYesterday = yesterdayCompleted.map(i => ({
  key: i.key,
  summary: i.fields?.summary?.substring(0, 60),
  project: i.fields?.project?.key
}));

// Calculate totals
const totalInProgress = Object.values(projects).reduce((s, p) => s + p.inProgress, 0);
const totalTodo = Object.values(projects).reduce((s, p) => s + p.todo, 0);
const totalBlocked = allBlockers.length;

return {
  json: {
    date: new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' }),
    timestamp: new Date().toISOString(),

    summary: {
      totalInProgress,
      totalTodo,
      totalBlocked,
      completedYesterdayCount: completedYesterday.length
    },

    projects,
    blockers: allBlockers,
    completedYesterday: completedYesterday.slice(0, 10),

    agents: agentStatus,
    staleAgents,

    hasBlockers: allBlockers.length > 0,
    hasStaleAgents: staleAgents.length > 0,
    needsAttention: allBlockers.length > 0 || staleAgents.length > 0 || agentStatus.error > 0
  }
};

const data = $json;

// Build standup sections
let standupText = '';

// Header
standupText += `## Daily Standup - ${data.date}\n\n`;

// Yesterday's Accomplishments
standupText += `### :white_check_mark: Completed Yesterday (${data.completedYesterday.length})\n`;
if (data.completedYesterday.length > 0) {
  data.completedYesterday.forEach(item => {
    standupText += `- **[${item.key}]** ${item.summary}\n`;
  });
} else {
  standupText += `- No issues completed yesterday\n`;
}
standupText += '\n';

// Today's Focus (high priority in progress)
standupText += `### :dart: Today's Focus\n`;
Object.values(data.projects).forEach(proj => {
  if (proj.highPriorityItems.length > 0) {
    standupText += `**${proj.projectKey}:**\n`;
    proj.highPriorityItems.forEach(item => {
      const statusEmoji = item.status === 'In Progress' ? ':construction:' : ':hourglass:';
      standupText += `- ${statusEmoji} **[${item.key}]** ${item.summary}\n`;
    });
  }
});
standupText += '\n';

// Blockers
standupText += `### :no_entry: Blockers (${data.blockers.length})\n`;
if (data.blockers.length > 0) {
  data.blockers.forEach(blocker => {
    standupText += `- :rotating_light: **[${blocker.key}]** ${blocker.summary}\n`;
  });
} else {
  standupText += `- No blockers! :tada:\n`;
}
standupText += '\n';

// Agent Status
standupText += `### :robot: Agent Health\n`;
standupText += `- Running: ${data.agents.running}/${data.agents.total}\n`;
if (data.agents.error > 0) {
  standupText += `- :warning: Agents in Error: ${data.agents.error}\n`;
}
if (data.staleAgents.length > 0) {
  standupText += `- :hourglass: Stale heartbeats: ${data.staleAgents.map(a => a.name).join(', ')}\n`;
}
standupText += '\n';

// Sprint Progress Summary
standupText += `### :bar_chart: Sprint Progress\n`;
standupText += `| Project | In Progress | To Do | Blocked |\n`;
standupText += `|---------|-------------|-------|---------|\n`;
Object.values(data.projects).forEach(proj => {
  standupText += `| ${proj.projectKey} | ${proj.inProgress} | ${proj.todo} | ${proj.blocked.length} |\n`;
});

// Determine embed color
let embedColor = 3066993; // Green
if (data.blockers.length > 2 || data.agents.error > 0) {
  embedColor = 15158332; // Red
} else if (data.blockers.length > 0 || data.staleAgents.length > 0) {
  embedColor = 16776960; // Yellow
}

return {
  json: {
    standupText,
    embed: {
      title: `:clipboard: Daily Standup - ${data.date}`,
      description: standupText.substring(0, 4000),
      color: embedColor,
      fields: [
        {
          name: ':bar_chart: In Progress',
          value: String(data.summary.totalInProgress),
          inline: true
        },
        {
          name: ':inbox_tray: To Do',
          value: String(data.summary.totalTodo),
          inline: true
        },
        {
          name: ':no_entry: Blocked',
          value: String(data.summary.totalBlocked),
          inline: true
        }
      ],
      footer: {
        text: 'SwjshAK Daily Standup | WF-A02'
      },
      timestamp: new Date().toISOString()
    },
    data,
    needsMGMTTicket: data.blockers.length > 0
  }
};

const error = $json;

return {
  json: {
    embed: {
      title: ':warning: Daily Standup Workflow Error',
      description: 'The standup compiler encountered an error.',
      color: 15158332,
      fields: [
        {
          name: 'Error',
          value: error.execution?.error?.message?.substring(0, 500) || 'Unknown',
          inline: false
        },
        {
          name: 'Node',
          value: error.execution?.error?.node?.name || 'Unknown',
          inline: true
        },
        {
          name: 'Time',
          value: new Date().toISOString(),
          inline: true
        }
      ],
      footer: { text: 'WF-A02 Error Handler' }
    }
  }
};
